import React from 'react';

import clsx from 'clsx';

import PohBadge, { BadgeVariant } from '@ui-kit/Badge/Badge';

import style from './style.module.less';

interface IBGUProps {
  portion: number;
  energy: number;
  protein: number;
  fat: number;
  carbohydrates: number;
  className?: string;
  unit: string;
}

const BGU = ({
  portion,
  energy,
  protein,
  fat,
  carbohydrates,
  className = '',
  unit = 'в порции',
}: IBGUProps) => {
  const [showPct, setShowPct] = React.useState(false);
  return (
    <PohBadge
      variant={BadgeVariant.Light}
      className={clsx('border', style.bgu, className)}
      onDoubleClick={(e) => {
        if (!portion) return;
        e.preventDefault();
        setShowPct((c) => !c);
        e.stopPropagation();
      }}
    >
      <span className={style.block}>
        <span className={style.portion} title={`Сухого вещества ${unit} (грамм)`}>
          {Math.round(portion)}
          <small>ГРАММ</small>
        </span>
        <span className={style.energy} title={`Энергетическая ценность ${unit} (ккал)`}>
          {Math.round(energy)}
          <small>ККАЛ</small>
        </span>
      </span>
      <span className={style.block} title={`Пищевая ценность ${unit}`}>
        <span className={style.protein}>
          {showPct ? <>{Math.round((protein / portion) * 100)}%</> : Math.round(protein)}
          <small>БЕЛКИ</small>
        </span>
        <span className={style.fat}>
          {showPct ? <>{Math.round((fat / portion) * 100)}%</> : Math.round(fat)}
          <small>ЖИРЫ</small>
        </span>
        <span className={style.carb}>
          {showPct ? (
            <>{Math.round((carbohydrates / portion) * 100)}%</>
          ) : (
            Math.round(carbohydrates)
          )}
          <small>УГЛЕВ</small>
        </span>
      </span>
    </PohBadge>
  );
};

export default BGU;
